/** `<argus-column>` as an Angular component, on the element's own tag. */
@Component({
  selector: 'argus-column',
  template: '<ng-content />',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class ArgusColumnComponent<T = unknown> {
  /** The `<argus-column>` element. */
  readonly element: ArgusColumnElement<T> =
    inject<ElementRef<ArgusColumnElement<T>>>(ElementRef).nativeElement;

  /** Stable key, used in state objects, events and persistence. Must be unique within the table. */
  @Input() set columnId(value: ArgusColumnElement<T>['columnId'] | null | undefined) {
    setProperty(this.element, 'columnId', 'column-id', value);
  }

  /** Header content: text as an attribute; a Lit template, a node or a function as a property. A function gets a `HeaderContext`: with `text: true`, return the column's name as plain text (for menus, exports and announcements). */
  @Input() set header(value: AngularColumnDef<T>['header'] | null | undefined) {
    setProperty(this.element, 'header', 'header', value);
  }

  /** How to read the cell value: a property path such as `customer.name`, or (as a property) a function of the row and its index. */
  @Input() set accessor(value: ArgusColumnElement<T>['accessor'] | null | undefined) {
    setProperty(this.element, 'accessor', 'accessor', value);
  }

  /** A spreadsheet formula computed per row from other columns, such as `[price] * [quantity]`. Needs the `formulas()` plugin from `@argus-table/formulas`. */
  @Input() set formula(value: ArgusColumnElement<T>['formula'] | null | undefined) {
    setProperty(this.element, 'formula', 'formula', value);
  }

  /** Cell content from the row: `(row, context) => content`. Property only; wins over a `<template>` child. */
  @Input() set cell(
    value: ((row: T, context: CellContext<T>) => AngularCellContent) | null | undefined,
  ) {
    setProperty(this.element, 'cell', undefined, value);
  }

  /** Width: `90` (px), `auto` to fit the content, or `2fr` for a share of the free space. Default: 150 px. */
  @Input() set width(
    value:
      | ArgusColumnElement<T>['width']
      | `${number}`
      | `${number}px`
      | `${number}fr`
      | null
      | undefined,
  ) {
    setProperty(this.element, 'width', 'width', value);
  }

  /** Lower bound for resizing and for flex columns, in px. Default: 40. */
  @Input() set minWidth(value: ArgusColumnElement<T>['minWidth'] | `${number}` | null | undefined) {
    setProperty(this.element, 'minWidth', 'min-width', value);
  }

  /** Upper bound for resizing, in px. Default: no limit. */
  @Input() set maxWidth(value: ArgusColumnElement<T>['maxWidth'] | `${number}` | null | undefined) {
    setProperty(this.element, 'maxWidth', 'max-width', value);
  }

  /** Pins the column to the `start` or `end` side. The table's `columnPinning` overrides it. */
  @Input() set pin(value: ArgusColumnElement<T>['pin'] | null | undefined) {
    setProperty(this.element, 'pin', 'pin', value);
  }

  /** Whether the user can pin or unpin the column. Default: `true`; `pinnable="false"` turns it off. */
  @Input() set pinnable(
    value: ArgusColumnElement<T>['pinnable'] | '' | 'true' | 'false' | null | undefined,
  ) {
    setProperty(this.element, 'pinnable', 'pinnable', value);
  }

  /** Whether the user can hide the column. Default: `true`; `hideable="false"` turns it off. */
  @Input() set hideable(
    value: ArgusColumnElement<T>['hideable'] | '' | 'true' | 'false' | null | undefined,
  ) {
    setProperty(this.element, 'hideable', 'hideable', value);
  }

  /** Text alignment: `start`, `center` or `end`. Default: `start`. */
  @Input() set align(value: ArgusColumnElement<T>['align'] | null | undefined) {
    setProperty(this.element, 'align', 'align', value);
  }

  /** Wraps the cell text onto more lines instead of cutting it off. Default: `false`. With a fixed row height, text that doesn't fit is clipped. */
  @Input() set wrap(
    value: ArgusColumnElement<T>['wrap'] | '' | 'true' | 'false' | null | undefined,
  ) {
    setProperty(this.element, 'wrap', 'wrap', value);
  }

  /** Whether the header can be clicked to sort. Default: `false`. */
  @Input() set sortable(
    value: ArgusColumnElement<T>['sortable'] | '' | 'true' | 'false' | null | undefined,
  ) {
    setProperty(this.element, 'sortable', 'sortable', value);
  }

  /** Whether the column can be resized. Default: `true`; `resizable="false"` turns it off. */
  @Input() set resizable(
    value: ArgusColumnElement<T>['resizable'] | '' | 'true' | 'false' | null | undefined,
  ) {
    setProperty(this.element, 'resizable', 'resizable', value);
  }

  /** Whether the column can be moved. Default: `true`; `reorderable="false"` turns it off. */
  @Input() set reorderable(
    value: ArgusColumnElement<T>['reorderable'] | '' | 'true' | 'false' | null | undefined,
  ) {
    setProperty(this.element, 'reorderable', 'reorderable', value);
  }

  /** The kind of filter users can set, e.g. from the column menu: `text`, `number`, `date` or `set`. Unset: users can't filter the column. */
  @Input() set filter(value: ArgusColumnElement<T>['filter'] | null | undefined) {
    setProperty(this.element, 'filter', 'filter', value);
  }

  /** Replaces the built-in matching for this column's filter. Property only. */
  @Input() set filterFn(value: ArgusColumnElement<T>['filterFn'] | null | undefined) {
    setProperty(this.element, 'filterFn', undefined, value);
  }

  /** The values a `set` filter offers; needed with a `dataSource`. Property only. */
  @Input() set filterOptions(value: ArgusColumnElement<T>['filterOptions'] | null | undefined) {
    setProperty(this.element, 'filterOptions', undefined, value);
  }

  /** Fields for plugins and the app (`ColumnDef.meta`), such as `meta.export`. Property only. */
  @Input() set meta(value: ArgusColumnElement<T>['meta'] | null | undefined) {
    setProperty(this.element, 'meta', undefined, value);
  }
}

